class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, c in enumerate(s):
            idx = ord(c) - 97  # ord('a') is 97
            mirror = 25 - idx
            if stacks[mirror]:
                j = stacks[mirror].pop()
                score += i - j
            else:
                stacks[idx].append(i)
        return score
